package com.renthouse.notification;import com.renthouse.auth.*;import com.renthouse.common.api.*;import java.time.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/v1/notifications")public class NotificationController{private final com.renthouse.notification.service.NotificationService s;public NotificationController(com.renthouse.notification.service.NotificationService s){this.s=s;}@GetMapping public ApiResponse<PageResponse<Item>>list(@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="20")int size){return ApiResponse.ok(s.list(page,size));}@GetMapping("/unread-count")public ApiResponse<Long>unread(){return ApiResponse.ok(s.unreadCount());}@PostMapping("/{id}/read")public ApiResponse<Void>read(@PathVariable long id){s.read(id);return ApiResponse.ok();}@PostMapping("/read-all")public ApiResponse<Void>readAll(){s.readAll();return ApiResponse.ok();}public record Item(String id,String type,String title,String content,boolean unread,LocalDateTime createdAt){}}
